window.CONDUTAS = window.CONDUTAS || {};
window.CONDUTAS["aula-08"] = {"aula": "aula-08", "aviso": "Material de estudo. Doses são faixas usuais de adulto, para revisão. Antes de prescrever, conferir a bula atual da Anvisa, o protocolo do serviço e o quadro do paciente (função renal e hepática, peso, idade, gestação, alergias, medicações em uso). Medicações com 'ver conduta da lombociatalgia' têm mecanismo e detalhes naquela conduta.", "condutas": [{"id": "lombociatalgia-l5", "titulo": "Lombociatalgia com radiculopatia L5 por hérnia discal L4-L5", "caso": "Caso integrador do Sr. Raimundo (aula 8, etapas 12 e 13)", "resumo": "Dor mecânica com irradiação ciática, déficit de L5 sem déficit progressivo, sem sinais de cauda equina. Conduta inicial conservadora, com reavaliação em 4 a 6 semanas.", "passos": [{"titulo": "1. Confirmar ausência de urgência", "texto": "Verificar sela, esfíncter e força a cada consulta. Ausência de retenção, incontinência, anestesia em sela e déficit progressivo. Se presente: urgência cirúrgica (RM e neurocirurgia)."}, {"titulo": "2. Orientar", "texto": "Explicar que a maioria das ciatalgias melhora com o tempo. Manter atividade leve e cotidiana. Evitar repouso no leito por mais de 2 dias."}, {"titulo": "3. Analgesia de base", "texto": "AINE (ibuprofeno) como primeira escolha medicamentosa quando o paciente deseja tratamento medicamentoso. Paracetamol como base ou alternativa se o AINE for contraindicado. Relaxante muscular de ação central por período curto, se houver contratura importante."}, {"titulo": "4. Proteção gástrica quando indicado", "texto": "Associar inibidor da bomba de prótons ao AINE se houver fator de risco para sangramento digestivo (idade acima de 65 anos, história de úlcera ou sangramento, uso de anticoagulante, corticoide ou antiagregante)."}, {"titulo": "5. Fisioterapia e exercício", "texto": "Exercício ativo e fortalecimento de core e de extensores do quadril. Ergonomia para levantamento de carga e postura sentada. Exercício ativo tem melhor evidência que repouso."}, {"titulo": "6. Evitar medicações sem evidência", "texto": "Gabapentinoides, corticoide oral de rotina e opioides não devem ser usados de rotina (ver seção de medicações não indicadas)."}, {"titulo": "7. Reavaliar em 4 a 6 semanas", "texto": "Escala de dor, força de hálux e dorsiflexão, sensibilidade de L5, Lasègue, Bragard, Schober e marcha. Piora de déficit ou dor refratária são indicação de encaminhamento."}, {"titulo": "8. Critérios para cirurgia", "texto": "Déficit motor progressivo ou importante; síndrome da cauda equina; dor refratária com incapacidade após período adequado de tratamento conservador (em geral cerca de 6 a 12 semanas, conforme protocolo); piora neurológica durante o tratamento."}], "medicacoes": [{"nome_comercial": "Ibuprofeno (ex.: Alivium, Advil)", "nome_generico": "Ibuprofeno", "classe": "Anti-inflamatório não esteroidal (AINE), derivado do ácido propiônico", "dose": "400 mg a 600 mg por tomada", "posologia": "VO a cada 8 horas, junto com alimento. Dose máxima usual de 2.400 mg/dia; alguns esquemas prescritos chegam a 3.200 mg/dia (teto). Conferir a bula. Usar pela menor dose eficaz e pelo menor tempo possível, em geral 1 a 2 semanas, com reavaliação.", "indicacao": "Dor radicular com componente inflamatório (edema e sensibilização da raiz L5). ACP 2017 o recomenda para lombalgia aguda e subaguda quando o paciente quer tratamento medicamentoso.", "porque": "Reduz a síntese de prostaglandinas no tecido inflamado ao redor da raiz comprimida. Isso diminui dor, sensibilização e edema.", "mecanismo": ["Quando o disco herniado irrita a raiz nervosa, as células do local liberam substâncias inflamatórias chamadas citocinas (ex.: IL-1 e TNF-α).", "As citocinas ativam uma enzima chamada fosfolipase A2, que solta o ácido araquidônico, uma gordura que faz parte da membrana das células.", "O ácido araquidônico é processado por duas enzimas, COX-1 e COX-2 (ciclo-oxigenases), que o transformam em prostaglandinas, como a PGE2.", "A PGE2 se liga a receptores EP nos nervos sensoriais. O nervo passa a disparar com estímulos fracos: isso é a sensibilização, a dor que fica mais intensa.", "O ibuprofeno se encaixa na COX e impede que ela produza prostaglandinas. O bloqueio é reversível: a droga se solta e a enzima volta a funcionar.", "Com menos prostaglandina, a raiz fica menos sensível e o edema ao redor do nervo diminui. A dor cai.", "Efeito indesejado: a COX-1 da parede do estômago produz prostaglandinas que protegem a mucosa. Sem elas, o estômago fica exposto ao ácido e pode ulcerar."], "efeitos_adversos": "Dispepsia, úlcera e sangramento digestivo; lesão renal, sobretudo com desidratação; hipertensão e retenção de líquidos; risco cardiovascular em uso prolongado ou em doses altas.", "contraindicacoes": "Úlcera péptica ativa, sangramento digestivo, insuficiência renal grave, insuficiência cardíaca descompensada, alergia a AINEs ou AAS, terceiro trimestre de gestação.", "cuidados": "Tomar com alimento. Evitar associar a outros AINEs e a corticoides sem indicação. Cuidado com anti-hipertensivos, diuréticos, anticoagulantes e metotrexato (interações).", "referencias": ["Vane JR. Inhibition of prostaglandin synthesis as a mechanism of action for aspirin-like drugs. Nature New Biology. 1971;231(25):232-5.", "Qaseem A et al. Ann Intern Med. 2017;166(7):514-530 (ACP: AINEs ou relaxantes para lombalgia aguda e subaguda, se o paciente preferir medicação)."], "termos": ["Receptor: proteína na superfície da célula que reconhece uma molécula específica e dispara uma resposta.", "Citocina: mensageiro químico da inflamação, liberado por células de defesa e tecidos lesados.", "COX (ciclo-oxigenase): enzima que transforma ácido araquidônico em prostaglandinas. Existem COX-1 (protetora, no estômago e rins) e COX-2 (induzida na inflamação).", "Prostaglandina: lipídio de sinalização que aumenta dor, febre e inflamação, e protege a mucosa gástrica (COX-1).", "Sensibilização: queda do limiar de disparo do nociceptor (neurônio de dor), que passa a responder a estímulos normais como se fossem dolorosos.", "Reversível: o fármaco se liga e se solta da enzima, sem destruí-la."], "linha": "1ª linha"}, {"nome_comercial": "Paracetamol (ex.: Tylenol, paracetamol genérico)", "nome_generico": "Paracetamol (acetaminofeno)", "classe": "Analgésico e antipirético não opioide", "dose": "500 mg a 1.000 mg por tomada", "posologia": "VO a cada 6 a 8 horas. Dose máxima: 4 g/dia para adulto (FDA, consumidor). Muitas fontes recomendam 3 g/dia em uso prolongado ou em risco de hepatotoxicidade (etilismo, desnutrição, uso de indutores enzimáticos). Confirmar na bula.", "indicacao": "Analgesia de base, ou alternativa se o AINE for contraindicado. Não é anti-inflamatório relevante.", "porque": "Atua principalmente no sistema nervoso central, reduzindo a percepção de dor, com pouca ação no tecido inflamado periférico. Por isso não reduz o edema da raiz.", "mecanismo": ["O paracetamol atravessa a barreira hematoencefálica e atua principalmente no sistema nervoso central (cérebro e medula), e pouco no tecido inflamado. Por isso é analgésico, mas não anti-inflamatório relevante.", "No sistema nervoso central, bloqueia de forma fraca a COX. Com menos prostaglandina central, o cérebro percebe a dor com menos intensidade.", "Parte do paracetamol é transformada, no fígado e no cérebro, em AM404: um metabólito, ou seja, um produto que o corpo cria ao processar a droga.", "O AM404 age em dois alvos. Um é o TRPV1, um canal iônico (poro na membrana que deixa passar íons) que se abre com calor e irritantes. Ao ser ativado pelo AM404, o canal fica dessensibilizado e para de enviar sinal de dor.", "O outro alvo é o sistema canabinoide: o AM404 aumenta o efeito de canabinoides naturais do corpo sobre o receptor CB1, que, ativado, reduz a liberação de neurotransmissores de dor.", "Esses efeitos ativam vias descendentes, que descem do cérebro para a medula e liberam serotonina e noradrenalina. Elas bloqueiam o sinal de dor na entrada da medula (corno dorsal).", "Resultado: menos sinal de dor chega ao cérebro.", "Toxicidade: em dose alta, outra via gera NAPQI, substância tóxica para o fígado. Ela é neutralizada pela glutationa; sem glutationa suficiente, lesa os hepatócitos."], "efeitos_adversos": "Em doses normais, poucos. Em excesso, hepatotoxicidade: o metabólito NAPQI, quando não é neutralizado pela glutationa, lesa hepatócitos.", "contraindicacoes": "Hepatopatia grave, alergia ao paracetamol. Cuidado em alcoolismo, desnutrição e jejum prolongado, que reduzem a glutationa.", "cuidados": "Verificar a soma com outros produtos que contêm paracetamol para não exceder a dose máxima. Em suspeita de intoxicação, antídoto: N-acetilcisteína.", "referencias": ["Qaseem A et al. Ann Intern Med. 2017;166(7):514-530 (ACP: paracetamol não superou placebo em lombalgia; por isso não é o principal tratamento).", "Bula do paracetamol aprovada pela Anvisa. Dose máxima conferida por busca (FDA: 4 g/dia; 3 g/dia em uso prolongado)."], "termos": ["Metabólito: substância produzida quando o organismo processa um fármaco.", "TRPV1: canal iônico sensível a calor e a substâncias irritantes, presente nos nociceptores. Ativá-lo de forma prolongada reduz a sensibilidade.", "Canal iônico: poro na membrana que deixa íons (Na+, K+, Ca2+) passar quando abre.", "CB1: receptor canabinoide, presente no sistema nervoso. Ativado, reduz a liberação de neurotransmissores.", "Via descendente: conjunto de neurônios que partem do tronco encefálico e modulam a dor na medula.", "Neurotransmissor: mensageiro químico entre neurônios (ex.: serotonina, noradrenalina, glutamato, substância P).", "Glutationa: antioxidante do fígado que neutraliza o NAPQI."], "linha": "1ª linha alternativa (base)"}, {"nome_comercial": "Ciclobenzaprina (ex.: Miosan)", "nome_generico": "Ciclobenzaprina (cloridrato)", "classe": "Relaxante muscular de ação central, estruturalmente relacionado aos antidepressivos tricíclicos", "dose": "5 mg a 10 mg por tomada", "posologia": "VO 3 vezes ao dia (ou 10 mg à noite). Dose máxima usual de 30 mg/dia. Uso por período curto, em geral até 2 a 3 semanas.", "indicacao": "Contratura paravertebral importante. Relaxante muscular é opção na lombalgia aguda e subaguda, segundo a ACP 2017.", "porque": "Reduz o tônus muscular de origem central, aliviando contratura e espasmo. Não atua diretamente no músculo, diferente de relaxantes que agem na fibra muscular.", "mecanismo": ["A ciclobenzaprina é quimicamente parecida com antidepressivos tricíclicos, mas age principalmente no tronco encefálico, a região do cérebro que regula o tônus muscular.", "Ela bloqueia três tipos de receptor: 5-HT2A (serotonina), α1 (noradrenalina) e muscarínicos (acetilcolina).", "Com esses receptores bloqueados, os neurônios motores do tronco disparam menos. O tônus de base dos músculos diminui.", "O fuso muscular (sensor de estiramento dentro do músculo) também deixa de enviar sinais exagerados de contração. O espasmo cede.", "A droga não age diretamente na fibra muscular. Por isso é um relaxante de ação central, e não um relaxante periférico.", "Efeitos de sedação e boca seca vêm do bloqueio de receptores de histamina e muscarínicos: a mesma ação que dá o efeito sedativo."], "efeitos_adversos": "Sonolência, tontura, boca seca, constipação, retenção urinária, visão turva, taquicardia.", "contraindicacoes": "Uso com inibidores da MAO (risco de síndrome serotoninérgica), glaucoma de ângulo fechado, retenção urinária, arritmias e infarto recente.", "cuidados": "Não dirigir nem operar máquinas. Usar à noite se houver sonolência. Evitar álcool e outros sedativos.", "referencias": ["Qaseem A et al. Ann Intern Med. 2017;166(7):514-530 (ACP: relaxantes musculares para lombalgia aguda e subaguda, como alternativa aos AINEs).", "Bula da ciclobenzaprina aprovada pela Anvisa. Dose conferida por busca: 5 mg 3x/dia, podendo chegar a 10 mg 3x/dia (teto de 30 mg/dia, para a forma de liberação imediata). Duração de 2 a 3 semanas citada em fonte. A forma de liberação prolongada é outro produto, com outra dose."], "termos": ["Tônus muscular: nível basal de contração de um músculo em repouso.", "Fuso muscular: sensor que detecta estiramento do músculo e envia sinal para a medula.", "Receptor muscarínico: receptor da acetilcolina (sistema nervoso parassimpático).", "Receptor 5-HT2A: receptor da serotonina.", "Receptor α1: receptor da noradrenalina.", "Tricíclico: classe química de antidepressivos com três anéis aromáticos."], "linha": "2ª linha"}, {"nome_comercial": "Omeprazol (ex.: Losec, Omeprazol genérico)", "nome_generico": "Omeprazol", "classe": "Inibidor da bomba de prótons (IBP)", "dose": "20 mg por tomada", "posologia": "VO 1 vez ao dia, de preferência antes do café da manhã, pelo período em que o AINE estiver sendo usado.", "indicacao": "Proteção da mucosa gástrica em paciente que usa AINE e tem fator de risco para sangramento digestivo.", "porque": "Reduz a acidez gástrica, que agrava a lesão da mucosa causada pelo AINE. Não protege contra lesão intestinal.", "mecanismo": ["As células parietais do estômago têm uma bomba, a H+/K+-ATPase, que joga íons H+ (ácido) para dentro do estômago.", "O omeprazol é absorvido e chega ao canalículo, um canal dentro da célula parietal, onde o pH é muito ácido.", "Nesse ambiente ácido, o omeprazol se transforma na forma ativa, a sulfenamida.", "A forma ativa se liga à bomba por ligação covalente, ou seja, uma ligação química forte e permanente. A bomba fica inativa.", "A bomba só volta a funcionar quando a célula produz uma nova. Por isso o efeito dura cerca de 24 horas, mesmo a droga sendo eliminada em poucas horas.", "Com menos ácido, a mucosa do estômago se recupera e fica protegida contra a lesão causada pelo AINE."], "efeitos_adversos": "Cefaleia, diarreia, dor abdominal. Em uso prolongado: menor absorção de magnésio, vitamina B12 e ferro, e risco de infecção por Clostridioides difficile.", "contraindicacoes": "Alergia ao omeprazol ou a outros IBPs. Cuidado com interações (clopidogrel: reduzir efeito; cetoconazol e itraconazol: absorção reduzida).", "cuidados": "Não usar como analgésico. Suspender quando o AINE for suspenso, se não houver outra indicação.", "referencias": ["Lanza FL et al. Guidelines for prevention of NSAID-related ulcer complications. Am J Gastroenterol. 2009;104(3):728-38. doi:10.1038/ajg.2009.115 (ACG: prevenção de complicações ulcerosas associadas a AINE).", "Bula do omeprazol aprovada pela Anvisa (conferir versão atual)."], "termos": ["Pró-fármaco: substância inativa que se converte na forma ativa dentro do organismo.", "Ligação covalente: ligação química forte, que não se desfaz com facilidade.", "Bomba H+/K+-ATPase: enzima que usa energia (ATP) para trocar H+ por K+ e produzir o ácido gástrico.", "Canalículo: pequeno canal da célula parietal onde o ácido é secretado."], "linha": "Adjuvante"}], "medicacoes_nao_indicadas": [{"nome_comercial": "Gabapentina (ex.: Neurontin) e pregabalina (ex.: Lyrica)", "nome_generico": "Gabapentina; pregabalina (gabapentinoides)", "classe": "Antiepiléptico ligante de subunidade α2δ de canais de cálcio", "por_que_nao_indicada": "NICE NG59 recomenda não oferecer gabapentinoides para ciatalgia. Metanálise (Enke et al., CMAJ 2018) não encontrou benefício frente a placebo para dor radicular lombar, com mais sonolência, tontura e náusea.", "mecanismo_para_estudo": ["Os canais de cálcio do tipo CaV2 têm uma subunidade chamada α2δ. Nos neurônios da medula e do gânglio da raiz, essa subunidade fica mais expressa quando há dor neuropática.", "Com mais canais ativos, entra mais cálcio no neurônio aferente. O cálcio é o sinal que faz as vesículas liberarem neurotransmissores.", "A gabapentina se liga à subunidade α2δ e reduz a entrada de cálcio.", "Com menos cálcio, o neurônio libera menos glutamato, substância P e CGRP no corno dorsal da medula.", "Em teoria, isso reduz a sensibilização central. Na prática, em ciatalgia, os estudos não mostraram benefício maior que o placebo, com mais sonolência e tontura."], "referencias": ["NICE NG59. Low back pain and sciatica in over 16s (atualização 2020): https://www.nice.org.uk/guidance/ng59", "Enke O et al. Anticonvulsants in the treatment of low back pain and lumbar radicular pain: a systematic review and meta-analysis. CMAJ. 2018;190(26):E786-E793. doi:10.1503/cmaj.171333."], "termos": ["Canal de cálcio CaV2: canal que deixa o cálcio entrar no neurônio quando abre.", "Subunidade α2δ: parte auxiliar do canal de cálcio, alvo da gabapentina e da pregabalina.", "Corno dorsal: região da medula que recebe os sinais de dor das raízes.", "CGRP: peptídeo liberado por neurônios de dor, que contribui para a sensibilização.", "Sensibilização central: aumento da resposta da medula à dor, mesmo sem estímulo forte."], "linha": "Não indicada"}, {"nome_comercial": "Prednisona (ex.: Meticorten)", "nome_generico": "Prednisona", "classe": "Glicocorticoide sistêmico", "por_que_nao_indicada": "NICE NG59 recomenda não oferecer corticoide oral para ciatalgia (não melhora dor nem função). A ACP 2017 também não encontrou benefício para dor aguda ou subaguda.", "mecanismo_para_estudo": ["O glicocorticoide atravessa a membrana da célula e se liga ao receptor de glicocorticoide (GR), que fica no citoplasma.", "O complexo entra no núcleo e se liga a trechos do DNA. Isso aumenta a produção de lipocortina (anexina A1) e reduz a produção de citocinas inflamatórias (IL-1, IL-6, TNF-α).", "A lipocortina inibe a fosfolipase A2, a mesma enzima do primeiro passo da inflamação do ibuprofeno. Com menos ácido araquidônico, a prostaglandina cai.", "Resultado: menos inflamação e menos edema ao redor da raiz. O efeito é rápido (horas).", "Mesmo assim, em ciatalgia o benefício clínico não foi demonstrado, e o efeito adverso é relevante."], "referencias": ["NICE NG59 (atualização 2020): https://www.nice.org.uk/guidance/ng59", "Qaseem A et al. Ann Intern Med. 2017;166(7):514-530 (corticoide sistêmico não eficaz para dor aguda ou subaguda)."], "termos": ["Receptor citoplasmático: receptor que fica dentro da célula e age dentro do núcleo.", "Transcrição: processo de copiar um gene do DNA para RNA, que depois vira proteína.", "Lipocortina (anexina A1): proteína que inibe a fosfolipase A2.", "Citocina: mensageiro químico da inflamação."], "linha": "Não indicada"}, {"nome_comercial": "Tramadol (ex.: Tramal) e outros opioides", "nome_generico": "Tramadol (e opioides em geral)", "classe": "Analgésico opioide", "por_que_nao_indicada": "ACP 2017 reserva tramadol e duloxetina para lombalgia crônica, após falha de tratamento não medicamentoso e AINE. NICE NG59 não recomenda opioides para ciatalgia crônica. Risco de dependência e de sedação.", "mecanismo_para_estudo": ["O tramadol tem dois mecanismos ao mesmo tempo.", "Primeiro, ele é um opioide fraco: liga-se ao receptor μ, que abre canais de potássio e fecha canais de cálcio nos neurônios de dor (ver morfina).", "Segundo, ele bloqueia os transportadores de serotonina e de noradrenalina. Esses transportadores retiram os neurotransmissores da fenda sináptica. Bloqueados, esses neurotransmissores ficam mais tempo ativos.", "As vias descendentes que saem do tronco encefálico e chegam à medula usam justamente serotonina e noradrenalina para bloquear a dor. Com mais desses neurotransmissores, o bloqueio fica mais forte.", "Efeitos: analgesia, mas também náusea, sonolência e risco de síndrome serotoninérgica se combinado com antidepressivos."], "referencias": ["Qaseem A et al. Ann Intern Med. 2017;166(7):514-530.", "NICE NG59 (atualização 2020): https://www.nice.org.uk/guidance/ng59"], "termos": ["Fenda sináptica: espaço entre dois neurônios onde os neurotransmissores são liberados.", "Transportador de recaptação: proteína que puxa o neurotransmissor de volta para dentro do neurônio.", "Síndrome serotoninérgica: excesso de serotonina no organismo, com agitação, tremor e febre; pode ser grave.", "Receptor μ: receptor opioide."], "linha": "3ª linha"}], "referencias_gerais": [{"texto": "NICE. Low back pain and sciatica in over 16s (NG59), atualização 2020. Referência localizada por busca; texto integral não lido.", "url": "https://www.nice.org.uk/guidance/ng59"}, {"texto": "Qaseem A et al. Noninvasive treatments for acute, subacute, and chronic low back pain. Ann Intern Med. 2017;166(7):514-530. Referência localizada por busca; texto integral não lido.", "url": "https://www.aafp.org/pubs/afp/issues/2017/0915/p407.html"}, {"texto": "Diretriz AMB/CFM (Projeto Diretrizes, 2001): lombalgias e lombociatalgias. Localizada por busca; texto integral não acessado.", "url": ""}, {"texto": "Diretriz AMB (Projeto Diretrizes, 2007): hérnia discal lombar. Indicação relativa de cirurgia em lombociatalgia resistente por mais de 12 semanas. Localizada por busca.", "url": ""}, {"texto": "PCDT do Ministério da Saúde para lombalgia (citado em revisão como de 2014). Versão vigente NÃO localizada. PENDENTE conferir em gov.br/saude.", "url": "https://www.gov.br/saude/pt-br/assuntos/pcdt"}, {"texto": "Enke O et al. Anticonvulsants in the treatment of low back pain and lumbar radicular pain: a systematic review and meta-analysis. CMAJ. 2018;190(26):E786-E793. doi:10.1503/cmaj.171333. Referência localizada por busca; texto integral não lido.", "url": "https://doi.org/10.1503/cmaj.171333"}], "hierarquia": ["Base não medicamentosa: exercício ativo, orientação e fisioterapia (ACP 2017; NICE NG59).", "1ª linha medicamentosa: AINE (ibuprofeno) por curto período, quando o paciente quer medicação (ACP 2017).", "1ª linha analgésica alternativa: paracetamol como base ou se o AINE for contraindicado. Eficácia limitada (ACP 2017: não superou placebo).", "2ª linha: relaxante muscular de curta duração (ciclobenzaprina) se houver contratura importante (ACP 2017).", "3ª linha: tramadol somente após falha das anteriores e com acompanhamento especializado (ACP 2017; NICE NG59).", "Adjuvante: inibidor da bomba de prótons (omeprazol) junto com AINE, em paciente de risco gástrico.", "Não usar de rotina: gabapentinoides e corticoide oral (NICE NG59; Enke et al., CMAJ 2018)."]}, {"id": "artrite-septica", "titulo": "Monoartrite aguda: artrite séptica", "caso": "Red flag da aula 8 (monoartrite aguda quente, com febre, em horas a dias)", "resumo": "Artrite séptica é urgência ortopédica e infecciosa. Tratar como infecção até prova em contrário: artrocentese com análise do líquido, hemoculturas, antibiótico IV empírico e drenagem articular. Não atrasar o antibiótico por causa de exames.", "passos": [{"titulo": "1. Reconhecer e internar", "texto": "Articulação quente, edemaciada, muito dolorosa, com febre e instalação em horas a dias. Monoartrite aguda de joelho ou quadril é a apresentação mais comum. Avaliar sinais de sepse e estabilidade hemodinâmica."}, {"titulo": "2. Exames iniciais", "texto": "Hemograma com contagem de leucócitos, VHS e PCR, hemoculturas (pelo menos 2 amostras, antes do antibiótico), glicemia e função renal. Radiografia da articulação. Ultrassonografia para derrame, se disponível."}, {"titulo": "3. Artrocentese diagnóstica e terapêutica", "texto": "Coletar líquido sinovial para contagem celular e diferencial, Gram, cultura e pesquisa de cristais (gota, pseudogota). Contagem acima de 50.000 células/mm³ com predomínio de neutrófilos é altamente suspeita. A punção também alivia a dor e o derrame."}, {"titulo": "4. Antibiótico empírico IV, sem esperar a cultura", "texto": "Esquema usual: vancomicina (cobre Staphylococcus aureus, incluindo MRSA) associada a uma cefalosporina de 3ª geração (ceftriaxona), que cobre Gram-negativos e Neisseria gonorrhoeae. A escolha depende do Gram, do risco e do protocolo local. Ajustar após a cultura."}, {"titulo": "5. Drenagem articular", "texto": "Artrocentese repetida ou drenagem cirúrgica (artroscopia ou artrotomia com lavagem) em articulação de carga, com líquido purulento, ou com falha clínica do tratamento antibiótico. Articulação de quadril tem indicação de drenagem mais precoce."}, {"titulo": "6. Imobilização e repouso curto", "texto": "Repouso articular durante a fase aguda, com mobilização precoce assim que a dor permitir. Evitar imobilização prolongada, que causa rigidez."}, {"titulo": "7. Duração e reavaliação", "texto": "Após a cultura, manter a terapia específica por tempo guiado pelo patógeno e pela drenagem. A literatura descreve de 2 a 4 semanas de antibiótico, em geral IV e depois VO, com variação entre fontes. Reavaliar clinicamente e por PCR a cada semana."}, {"titulo": "8. Investigar a causa", "texto": "Gonococo (uretrite, lesões de pele, poliarticulação), trauma, injeção articular recente, prótese, imunossupressão e diabetes. Gonococo exige protocolo próprio."}], "medicacoes": [{"nome_comercial": "Vancomicina (ex.: Vancocin)", "nome_generico": "Cloridrato de vancomicina", "classe": "Glicopeptídeo antibiótico (bactericida, Gram-positivos)", "dose": "Dose de ataque de 20 a 35 mg/kg (máximo 3 g), depois manutenção ajustada por AUC (alvo de AUC 400 a 600), conforme o consenso 2020 ASHP/IDSA/PIDS/SIDP; obesos: 20 a 25 mg/kg.", "posologia": "IV a cada 8 a 12 horas, com ajuste pela função renal. Monitorização guiada por AUC (consenso de 2020: AUC/MIC de 400 a 600, para MIC de 1 mg/L), quando disponível. Vale de 15 a 20 mg/L é alvo antigo.", "indicacao": "Cobertura empírica de Staphylococcus aureus, incluindo MRSA, até o resultado da cultura. S. aureus é o agente mais comum da artrite séptica em adultos.", "porque": "Evita falha de tratamento por cepa resistente à meticilina, que tem alta mortalidade e destruição articular rápida se não tratada.", "mecanismo": ["A parede das bactérias Gram-positivas é feita de peptidoglicano, uma malha de açúcares unidos por pequenas cadeias de aminoácidos.", "Na ponta dessas cadeias existe o terminal D-alanil-D-alanina, que as enzimas usam para unir as cadeias.", "A vancomicina se encaixa nesse terminal por ligações de hidrogênio (forças fracas, mas em vários pontos), como uma tampa.", "Com a tampa, as enzimas transglicosilase e transpeptidase não conseguem unir as cadeias.", "A parede fica frouxa. A bactéria não suporta a pressão interna e morre (efeito bactericida, mas lento).", "Como não atravessa a membrana externa das bactérias Gram-negativas, a vancomicina não atua contra elas."], "efeitos_adversos": "Nefrotoxicidade (sobretudo com outros nefrotóxicos e em idosos), ototoxicidade, reação de infusão (síndrome do homem vermelho: prurido e rubor, por infusão rápida), flebite, neutropenia.", "contraindicacoes": "Alergia à vancomicina. Cuidado com insuficiência renal e com ototoxicidade prévia.", "cuidados": "Infundir lentamente (em geral 1 a 2 horas). Monitorar função renal e nível sérico. Evitar combinações com outros nefrotóxicos quando possível.", "referencias": ["Schermerhorn. Septic arthritis (Hospital Medicine). Referência localizada por busca; texto integral não lido.", "Diretriz argentina de artritis séptica (2023). Referência localizada por busca; texto integral não lido.", "Rybak MJ et al. Therapeutic monitoring of vancomycin for serious MRSA infections: a revised consensus guideline. Am J Health-Syst Pharm. 2020;77(11):835-864 (doi:10.1093/ajhp/zxaa036). Alvo AUC/MIC 400 a 600 para MIC 1 mg/L (A-II). Referência localizada por busca; texto integral não lido."], "termos": ["Gram-positivo: bactéria com parede espessa de peptidoglicano e sem membrana externa (ex.: Staphylococcus aureus).", "Peptidoglicano: polímero da parede bacteriana.", "Transglicosilase e transpeptidase: enzimas que montam e unem as cadeias da parede.", "Ligação de hidrogênio: atração fraca entre átomos de hidrogênio e oxigênio ou nitrogênio."], "linha": "1ª linha (empírica)"}, {"nome_comercial": "Ceftriaxona (ex.: Rocephin, ceftriaxona genérica)", "nome_generico": "Ceftriaxona sódica", "classe": "Cefalosporina de 3ª geração (β-lactâmico, bactericida)", "dose": "Gonorreia não complicada (CDC 2021): 500 mg IM dose única (1 g se 150 kg ou mais). Artrite gonocócica disseminada: 1 g IV ou IM a cada 24 horas (CDC 2021).", "posologia": "IV 1 vez ao dia (meia-vida longa). Ajustar pela gravidade e pelo protocolo.", "indicacao": "Cobertura de Gram-negativos e de Neisseria gonorrhoeae, associada à vancomicina no esquema empírico. Ajustar após a cultura e o Gram.", "porque": "Cobre bactérias que a vancomicina não cobre (Gram-negativos), e o gonococo, que é causa importante de artrite séptica em adultos jovens sexualmente ativos.", "mecanismo": ["A parede bacteriana é reticulada por enzimas chamadas PBPs (proteínas ligadoras de penicilina), que fazem as ligações finais.", "A ceftriaxona tem um anel β-lactâmico, que imita o terminal da parede e se encaixa na PBP.", "A ligação é irreversível: a PBP fica inativa.", "Sem PBP funcionando, a parede não se fecha e a bactéria se rompe.", "A ceftriaxona atravessa a membrana externa dos Gram-negativos por canais chamados porinas, por isso atua neles também.", "Meia-vida longa: o fármaco permanece no sangue por muitas horas, e uma dose diária basta."], "efeitos_adversos": "Reações alérgicas (inclusive anafilaxia), diarreia por Clostridioides difficile, cálculos biliares (precipitação de ceftriaxona-cálcio), leucopenia e trombocitopenia.", "contraindicacoes": "Alergia grave a β-lactâmicos (penicilinas e cefalosporinas). Cuidado em reação prévia a penicilina, por reação cruzada.", "cuidados": "Não diluir no mesmo frasco com vancomicina ou fluconazol (bula Triaxon). Administrar separadamente. Evitar em recém-nascidos com hiperbilirrubinemia.", "referencias": ["Bula Triaxon (Roche), Anvisa: posologia lida no texto da bula (PDF de saudedireta.com.br). Dados da bula são antigos para gonorreia.", "Workowski AA et al. Sexually Transmitted Infections Treatment Guidelines, 2021. MMWR Recomm Rep. 2021;70(4). Trecho do PDF citado (p. 79), fonte secundária: ceftriaxona 1 g IM ou IV a cada 24 h na artrite gonocócica."], "termos": ["β-lactâmico: anel químico característico de penicilinas e cefalosporinas.", "PBP: enzima que reticula a parede; é o alvo dos β-lactâmicos.", "Porina: canal da membrana externa dos Gram-negativos.", "Meia-vida: tempo para a concentração da droga cair pela metade."], "linha": "1ª linha (empírica)"}, {"nome_comercial": "Paracetamol (ex.: Tylenol)", "nome_generico": "Paracetamol", "classe": "Analgésico não opioide", "dose": "500 mg a 1.000 mg por tomada", "posologia": "VO a cada 6 a 8 horas. Máximo 3 g/dia (ou 4 g/dia, conforme bula e risco do paciente).", "indicacao": "Analgesia durante a infecção. Evitar AINE em altas doses como analgésico de primeira linha sem avaliar função renal e risco digestivo.", "ref": "Paracetamol", "porque_ref": "Ver mecanismo na conduta da lombociatalgia.", "linha": "Adjuvante"}], "medicacoes_nao_indicadas": [{"nome_comercial": "Corticoide sistêmico e corticoide intra-articular antes do diagnóstico", "nome_generico": "Prednisona; metilprednisolona; triancinolona (intra-articular)", "classe": "Glicocorticoide", "por_que_nao_indicada": "Pode mascarar a infecção e piorar a destruição articular. Não usar antes da artrocentese e da confirmação da causa. Ver mecanismo na conduta da lombociatalgia (prednisona).", "mecanismo_para_estudo": ["Glicocorticoides reduzem a inflamação e a resposta imune local.", "Sem antibiótico adequado, a bactéria se multiplica com menos resposta do hospedeiro.", "Resultado: a infecção pode avançar sem sinais clínicos claros."], "referencias": ["Regra clínica geral de artrite séptica: diagnóstico por artrocentese antes de qualquer corticoide intra-articular."], "linha": "Não indicada antes do diagnóstico"}], "referencias_gerais": [{"texto": "Schermerhorn. Septic arthritis (material de apoio, Hospital Medicine). Referência localizada por busca; texto integral não lido.", "url": "https://hospitalmedicine.org/globalassets/professional-development/clinical-quick-talks-pdfs/septic-arthritis-schermerhorn.pdf"}, {"texto": "Diretriz argentina de artritis séptica (Ministerio de Salud de Córdoba, 2023): ceftriaxona + vancomicina empíricas, ajuste pelo antibiograma. Referência localizada por busca; texto integral não lido.", "url": "https://ministeriodesalud.cba.gov.ar/wp-content/uploads/2023/11/Artritis-septica.pdf"}, {"texto": "Matos et al., Rev Bras Ortop, 2006: citado por Estratégia MED para oxacilina de 2 a 4 semanas em artrite não gonocócica. Original NÃO acessado. PENDENTE conferir.", "url": ""}, {"texto": "Sem PCDT nacional. Protocolo de regulação de Santa Catarina trata a suspeita de artrite séptica como sinal de alarme, com encaminhamento à emergência (risco vermelho). Diretriz SBOT ou SBI: não localizada. Internacional: Mathews CJ et al. Lancet 2010;375:846-855 (citação lida por busca, texto não lido). Antibiótico empírico logo após a artrocentese; vancomicina mais ceftriaxona para cocos Gram-positivos em cadeia (Schermerhorn, resumo).", "url": ""}], "hierarquia": ["1ª linha empírica: vancomicina + ceftriaxona IV, até o resultado da cultura (Schermerhorn; diretriz argentina 2023).", "2ª linha (após cultura): ajuste ao germe. Estafilococo sensível à meticilina: oxacilina por 2 a 4 semanas (Estratégia MED, citando Matos et al., 2006). Gonococo: ceftriaxona.", "3ª linha: alternativas conforme antibiograma, com infectologia.", "Adjuvante: analgesia (paracetamol) e drenagem articular.", "Evitar: corticoide intra-articular ou sistêmico antes do diagnóstico."]}, {"id": "ruptura-tendao-calcaneo", "titulo": "Ruptura do tendão calcâneo (teste de Thompson positivo)", "caso": "Aula 8: teste de Thompson (decúbito ventral, sem flexão plantar à compressão do tríceps sural)", "resumo": "Ruptura completa do tendão de Aquiles, com perda da flexão plantar ativa. Conduta: confirmação com ultrassonografia ou RM, decisão entre reparo cirúrgico e tratamento funcional, e profilaxia de trombose durante a imobilização. Medicamentos são de suporte.", "passos": [{"titulo": "1. Confirmar o diagnóstico", "texto": "Teste de Thompson positivo, falha palpável no trajeto do tendão, incapacidade de ficar na ponta do pé. Confirmar com ultrassonografia (rápida, à beira do leito) ou RM."}, {"titulo": "2. Decidir o tratamento", "texto": "Reparo cirúrgico ou tratamento funcional com imobilização em equino (pé em flexão plantar), com reabilitação progressiva. A decisão depende de idade, atividade, comorbidades e risco cirúrgico. A literatura brasileira consultada tende a favorecer a cirurgia em paciente ativo, pela menor taxa de rerruptura (Mansur et al., Rev Bras Ortop, 2021). A decisão é individual."}, {"titulo": "3. Imobilização", "texto": "Imobilização com tala ou bota em equino, com joelho levemente fletido. Descarregar o peso conforme orientação. Trocar o gesso ou a bota após a fase inicial, conforme o protocolo."}, {"titulo": "4. Profilaxia de trombose", "texto": "Paciente imobilizado de membro inferior tem risco de trombose venosa profunda. Avaliar risco e, se indicado, prescrever profilaxia com enoxaparina (ver abaixo)."}, {"titulo": "5. Analgesia e orientação", "texto": "Elevar o membro, aplicar gelo nas primeiras 48 a 72 horas, usar analgésico. Não apoiar peso sem orientação."}, {"titulo": "6. Reabilitação", "texto": "Fisioterapia com carga progressiva após a fase de imobilização, para recuperar força e amplitude de flexão plantar."}], "medicacoes": [{"nome_comercial": "Enoxaparina (ex.: Clexane)", "nome_generico": "Enoxaparina sódica", "classe": "Heparina de baixo peso molecular (anticoagulante)", "dose": "40 mg por dose, SC, para paciente de alto risco de TEV (20 mg em algumas tabelas para risco moderado). Ajustar por peso e função renal", "posologia": "SC 1 vez ao dia, pelo período de imobilização ou conforme o protocolo do serviço.", "indicacao": "Profilaxia de trombose venosa profunda em paciente imobilizado de membro inferior com risco aumentado (idade, obesidade, cirurgia, câncer, histórico de trombose).", "porque": "A imobilização reduz o retorno venoso da panturrilha e favorece a formação de trombos. A profilaxia reduz esse risco.", "mecanismo": ["A antitrombina III é uma proteína do sangue que bloqueia naturalmente fatores de coagulação.", "A enoxaparina é um fragmento de heparina. Ela se liga à antitrombina e a torna muito mais eficaz.", "O principal alvo é o fator Xa, que transforma a protrombina em trombina.", "Com menos trombina, a fibrina (a rede que segura o coágulo) não se forma. O trombo não cresce.", "Em relação à heparina comum, o efeito é mais previsível e dispensa controle frequente, mas ainda exige ajuste pelo peso e pela função renal."], "efeitos_adversos": "Sangramento, hematoma no local da injeção, trombocitopenia induzida por heparina (plaquetas em queda), elevação de transaminases.", "contraindicacoes": "Sangramento ativo, plaquetopenia grave, história de trombocitopenia induzida por heparina, alergia. Cuidado em insuficiência renal grave.", "cuidados": "Verificar função renal e plaquetas. Não associar a AINE sem indicação. Monitorar sinais de sangramento.", "referencias": ["Queensland Health. Lower limb injury VTE prophylaxis (pathway). Referência localizada por busca; texto integral não lido.", "NHS Lanarkshire / Right Decisions (Escócia). Immobilised lower limb injury enoxaparin prescribing guidance (2025). Referência localizada por busca; texto integral não lido.", "Diretriz brasileira de TEV: NÃO localizada. PENDENTE conferir (ex.: SBACV, SBOT, Ministério da Saúde)."], "termos": ["Fator de coagulação: proteína do plasma que participa da formação do coágulo.", "Trombina: enzima que converte fibrinogênio em fibrina.", "Fibrina: proteína que forma a rede do coágulo.", "Heparina de baixo peso molecular: fragmento de heparina com efeito mais previsível."], "linha": "Adjuvante condicional"}, {"nome_comercial": "Ibuprofeno", "ref": "Ibuprofeno", "indicacao": "Analgesia e controle do edema nas primeiras semanas.", "porque": "Reduzir dor e edema no período inicial.", "linha": "1ª linha analgésica (curto prazo)"}, {"nome_comercial": "Paracetamol", "ref": "Paracetamol", "indicacao": "Analgesia de base, sem efeito anti-inflamatório relevante.", "porque": "Dor sem risco gástrico do AINE.", "linha": "1ª linha analgésica"}], "referencias_gerais": [{"texto": "Mansur et al. Lesões do tendão de Aquiles, parte 2 (rupturas). Rev Bras Ortop, 2021. Localizada por busca; conferir o link e o texto integral.", "url": "https://rto.emnuvens.com.br/revista/article/download/440/433/661"}, {"texto": "Série de casos, Rev ABTPé (2010): rerruptura média de 4% com cirurgia. Localizada por busca; autores não confirmados.", "url": ""}, {"texto": "Diretriz SBOT para ruptura do tendão de Aquiles: NÃO localizada. Artigo brasileiro: Mansur NSB et al. Lesões do Aquiles – Parte 2: Rupturas. Rev Bras Ortop. 2021;55(6):665-672 (doi:10.1055/s-0040-1702948). Estudo prognóstico, não diretriz. Ensaio CARTA (Toft et al., BJSM 2026, lido por resumo): algoritmo pela elongação do tendão após ruptura aguda. Elongação de 7% ou mais, cirurgia; menos de 7%, não operatório. Escore TRS 65 vs 57 em 12 meses. Diretriz SBOT: não localizada.", "url": ""}], "hierarquia": ["Tratamento principal: não medicamentoso. Cirurgia ou funcional com imobilização (Mansur et al., 2021).", "1ª linha analgésica: paracetamol e AINE por curto período.", "Adjuvante condicional: profilaxia de trombose com enoxaparina, se o risco for alto durante a imobilização."]}, {"id": "lesao-lca-hemartrose", "titulo": "Entorse com derrame volumoso: suspeita de lesão do LCA (hemartrose)", "caso": "Aula 8: torção com estalido, derrame volumoso nas primeiras horas, falseio e teste de Lachman positivo", "resumo": "Derrame volumoso nas primeiras horas (hemartrose) com instabilidade sugere lesão do LCA. Conduta: proteger a articulação, aliviar o derrame, analgesia, imagem e encaminhamento ortopédico. Cirurgia depende da instabilidade e da demanda do paciente.", "passos": [{"titulo": "1. Excluir urgência", "texto": "Avaliar pulsos distais, perfusão e sensibilidade. Deformidade grave, luxação ou sinais de isquemia são urgências. Imobilizar e encaminhar."}, {"titulo": "2. Proteger e aliviar", "texto": "Repouso relativo, elevação, gelo nas primeiras 48 horas, compressão leve. Imobilização com órtese, se houver instabilidade."}, {"titulo": "3. Esvaziar o derrame", "texto": "Derrame tenso limita a mobilidade e causa dor. Artrocentese para alívio, com cuidado para não contaminar a articulação."}, {"titulo": "4. Analgesia", "texto": "Paracetamol como base e AINE por curto período, se não houver contraindicação."}, {"titulo": "5. Imagem", "texto": "Radiografia para excluir fratura (fratura osteocondral, avulsão). RM para avaliar o LCA, meniscos e cartilagem. A RM é o método de escolha para lesões ocultas."}, {"titulo": "6. Encaminhar e reabilitar", "texto": "Ortopedia para decidir entre reconstrução cirúrgica e tratamento conservador, conforme idade, atividade e instabilidade. Fisioterapia para força de quadríceps e isquiotibiais, e propriocepção."}, {"titulo": "7. Cuidados com o menisco", "texto": "Bloqueio mecânico ou derrame recorrente sugerem lesão meniscal associada. Reavaliar com RM."}], "medicacoes": [{"nome_comercial": "Ibuprofeno", "ref": "Ibuprofeno", "indicacao": "Analgesia e controle da inflamação na fase aguda da lesão.", "porque": "Reduzir dor e edema no período inicial.", "linha": "2ª linha"}, {"nome_comercial": "Paracetamol", "ref": "Paracetamol", "indicacao": "Analgesia de base, sem efeito anti-inflamatório relevante.", "porque": "Dor sem risco gástrico do AINE.", "linha": "1ª linha"}], "referencias_gerais": [{"texto": "Diretriz AMB/CFM/SBOT (2007): diagnóstico da lesão do LCA. Localizada por busca; cita Lachman em 72% das hemartroses e 77% de lesão do LCA em 132 pacientes.", "url": ""}, {"texto": "AAOS. Management of Anterior Cruciate Ligament Injuries: clinical practice guideline. J Am Acad Orthop Surg. 2015;23:e1-e5 (resumo; diretriz de 2014). A AAOS publicou versão nova em 22/08/2022: conferir. Conteúdo não lido na íntegra.", "url": ""}, {"texto": "Sem PCDT nacional de rotura do LCA (parecer TJRJ: não encontrado na base do Ministério da Saúde). No SUS, a reconstrução consta no SIGTAB (média complexidade; nota técnica TJMG). Diretriz SBOT: não localizada.", "url": ""}], "hierarquia": ["Tratamento principal: proteção, órtese, artrocentese para alívio do derrame, imagem e ortopedia.", "1ª linha analgésica: paracetamol.", "2ª linha: AINE por curto período, se não houver contraindicação."]}, {"id": "artrite-reumatoide", "titulo": "Artrite reumatoide inicial (poliartrite simétrica)", "caso": "Caso da aula 8: paciente de 36 anos, rigidez matinal de 90 min, sinovite em MCF e IFP, simétrica", "resumo": "AR é doença inflamatória crônica que precisa de tratamento precoce com DMARD para evitar erosões. Metotrexato é o DMARD de primeira linha. Glicocorticoide é ponte curta, e não tratamento de longo prazo.", "passos": [{"titulo": "1. Confirmar o diagnóstico", "texto": "Fator reumatoide e anti-CCP, VHS e PCR, radiografias de mãos e pés. Excluir outras causas de poliartrite. Avaliar manifestações extra-articulares."}, {"titulo": "2. Iniciar DMARD precoce", "texto": "Tratar cedo, porque o dano articular ocorre nos primeiros meses. Metotrexato é a primeira escolha em paciente com atividade moderada a alta, segundo o ACR 2021."}, {"titulo": "3. Glicocorticoide em ponte, por pouco tempo", "texto": "Prednisona em dose baixa, por pouco tempo, enquanto o DMARD faz efeito (que demora semanas). O ACR 2021 recomenda minimizar glicocorticoide de uso prolongado. O EULAR aceita o uso curto com desmame rápido."}, {"titulo": "4. Monitorar toxicidade", "texto": "Hemograma, função hepática e renal conforme o protocolo do serviço (em geral a cada 2 a 4 semanas no início, depois com menos frequência). Orientar sobre infecções e vacinas."}, {"titulo": "5. Meta de tratamento", "texto": "Tratar para remissão ou baixa atividade, com avaliação periódica por escala validada. Ajustar o tratamento se não atingir a meta em cerca de 3 a 6 meses."}, {"titulo": "6. Orientar", "texto": "Fisioterapia, exercício de baixo impacto, terapia ocupacional para mãos e controle do tabagismo (que piora a doença)."}], "medicacoes": [{"nome_comercial": "Metotrexato (ex.: Ritmo, Metotrexato genérico)", "nome_generico": "Metotrexato", "classe": "DMARD sintético convencional (antimetabólito, antagonista do folato)", "dose": "Início usual com alvo de pelo menos 15 mg por semana em 4 a 6 semanas (ACR 2021); dose máxima conforme bula e protocolo.", "posologia": "VO, SC ou IM, 1 vez por semana (nunca diariamente). Conitec 1.021 (2026): dose semanal de 7,5 a 25 mg; se intolerância oral, dividir a dose ou usar injetável. Acompanhar com ácido fólico.", "indicacao": "Primeira escolha de DMARD em AR com atividade moderada a alta (ACR 2021). Controla a inflamação e reduz a progressão das erosões.", "porque": "Freia a proliferação das células de defesa que causam a sinovite, e reduz a destruição articular a longo prazo.", "mecanismo": ["O ácido fólico precisa ser transformado em tetra-hidrofolato pela enzima DHFR (di-hidrofolato redutase).", "O tetra-hidrofolato é necessário para fabricar as bases do DNA (purinas e timidina).", "O metotrexato bloqueia a DHFR. As células que mais se dividem, como os linfócitos ativados e as células do tecido inflamado da membrana sinovial, precisam de mais DNA e são as mais afetadas.", "Dentro da célula, o metotrexato se transforma em poliglutamato, que inibe a enzima AICAR transformilase. Com isso, a adenosina se acumula fora da célula.", "A adenosina se liga aos receptores A2A das células inflamatórias e reduz a liberação de citocinas, como o TNF-α.", "O efeito é lento (semanas a meses), porque depende da renovação celular e do acúmulo do fármaco."], "efeitos_adversos": "Náusea, aftas, cansaço, toxicidade hepática, mielossupressão, pneumonite e aumento de infecções. Em excesso: toxicidade grave, incluindo morte.", "contraindicacoes": "Gravidez e planejamento de gravidez (é teratogênico), insuficiência renal grave, hepatopatia, alcoolismo, imunodeficiência, infecção ativa e alergia.", "cuidados": "Dose semanal, em um dia fixo. Ácido fólico (5 mg por semana, ou 1 mg por dia), conforme o protocolo, para reduzir náusea e toxicidade. Evitar álcool. Não usar AINE em doses altas junto (aumenta toxicidade).", "referencias": ["Portaria Conjunta SAES/SCTIE nº 33, de 19/01/2026: PCDT da Artrite Reumatoide, Ministério da Saúde. Texto do PCDT final NÃO lido. PENDENTE conferir em gov.br/saude (PCDTs).", "Relatório de Recomendação Conitec nº 1.021 (2026), PCDT da AR. Texto lido: MTX VO, SC ou IM, 7,5 a 25 mg 1x/semana; MTX como 1ª escolha, com dose oral dividida ou injetável se intolerância.", "Fraenkel L et al. 2021 ACR Guideline for the Treatment of Rheumatoid Arthritis. Arthritis Care Res. 2021;73(7):924-939. doi:10.1002/acr.24596. Referência localizada por busca; texto integral não lido.", "Bula do metotrexato aprovada pela Anvisa: não acessada nesta busca. Conferir a versão atual."], "termos": ["DHFR: enzima que reduz o di-hidrofolato a tetra-hidrofolato.", "Purinas e timidina: bases do DNA e do RNA.", "Sinóvia: membrana que reveste a articulação; é o tecido que inflama na artrite.", "Receptor A2A da adenosina: receptor que, ativado, reduz a inflamação."], "linha": "1ª linha"}, {"nome_comercial": "Prednisona (ex.: Meticorten)", "nome_generico": "Prednisona", "classe": "Glicocorticoide sistêmico", "dose": "5 mg a 7,5 mg por dia, em ponte curta (dose individualizada e com desmame)", "posologia": "VO 1 vez ao dia, pela manhã. Reduzir até suspender, em geral em alguns meses, conforme a resposta ao DMARD.", "indicacao": "Ponte enquanto o DMARD faz efeito, em paciente com sintomas intensos. Não é tratamento de longo prazo.", "porque": "Controla a inflamação rapidamente, enquanto o metotrexato ainda não agiu.", "mecanismo": ["O glicocorticoide atravessa a membrana da célula e se liga ao receptor de glicocorticoide (GR), que fica no citoplasma.", "O complexo entra no núcleo e se liga a trechos do DNA. Isso aumenta a produção de lipocortina (anexina A1) e reduz a produção de citocinas inflamatórias (IL-1, IL-6, TNF-α).", "A lipocortina inibe a fosfolipase A2, a mesma enzima do primeiro passo da inflamação do ibuprofeno. Com menos ácido araquidônico, a prostaglandina cai.", "Resultado: menos inflamação e menos edema ao redor da raiz. O efeito é rápido (horas).", "Mesmo assim, em ciatalgia o benefício clínico não foi demonstrado, e o efeito adverso é relevante."], "efeitos_adversos": "Glicemia alta, insônia, hipertensão, retenção de líquido, infecções, osteoporose e miopatia com uso prolongado.", "contraindicacoes": "Infecção não controlada, osteoporose grave, úlcera ativa, diabetes descompensado, psicose.", "cuidados": "Desmame gradual para evitar insuficiência adrenal. Usar a menor dose pelo menor tempo.", "referencias": ["NICE NG59 (atualização 2020).", "Fraenkel L et al. 2021 ACR guideline (glicocorticoide mínimo e por pouco tempo). Verificar o texto completo."], "termos": ["Receptor citoplasmático: receptor que fica dentro da célula e age dentro do núcleo.", "Transcrição: processo de copiar um gene do DNA para RNA, que depois vira proteína.", "Lipocortina (anexina A1): proteína que inibe a fosfolipase A2.", "Citocina: mensageiro químico da inflamação."], "linha": "Adjuvante (ponte curta)"}, {"nome_comercial": "Ácido fólico (ex.: Fólico genérico)", "nome_generico": "Ácido fólico (folato)", "classe": "Vitamina do complexo B (suplemento)", "dose": "Conforme protocolo local (1 mg/dia ou 5 mg/semana); a conferir.", "posologia": "VO. Em geral no dia seguinte à dose semanal de metotrexato, para reduzir a toxicidade sem diminuir a eficácia.", "indicacao": "Reduzir efeitos adversos do metotrexato (náusea, aftas, toxicidade hepática e mielossupressão).", "porque": "O metotrexato bloqueia a DHFR, e o folato suplementar contorna parte desse bloqueio nas células normais.", "mecanismo": ["O ácido fólico fornece folato, que a célula transforma em tetra-hidrofolato sem depender tanto da DHFR.", "Assim, as células normais (mucosa, medula, fígado) têm mais tetra-hidrofolato disponível e se recuperam do bloqueio causado pelo metotrexato.", "O efeito anti-inflamatório do metotrexato sobre as células doentes permanece, porque a dose de folato não reverte o bloqueio nas células que se dividem sem controle."], "efeitos_adversos": "Raros. Pode mascarar deficiência de vitamina B12 se usado isoladamente em altas doses.", "contraindicacoes": "Alergia. Cuidado com anemia megaloblástica não diagnosticada (avaliar B12 antes).", "cuidados": "Tomar no dia seguinte ao metotrexato, conforme o protocolo do serviço.", "referencias": ["Fraenkel L et al. 2021 ACR guideline (2021). Verificar o texto completo sobre folato.", "Bula do ácido fólico aprovada pela Anvisa (conferir versão atual)."], "termos": ["Folato: forma natural da vitamina B9.", "Tetra-hidrofolato: forma ativa do folato, usada para fabricar DNA."], "linha": "Adjuvante"}, {"nome_comercial": "Ibuprofeno (AINE, uso sintomático)", "nome_generico": "Ibuprofeno", "classe": "AINE", "dose": "Ver conduta da lombociatalgia", "posologia": "Ver conduta da lombociatalgia", "indicacao": "Alívio sintomático de dor e rigidez, sem efeito sobre a progressão da AR.", "porque": "Reduzir a dor enquanto o DMARD faz efeito.", "ref": "Ibuprofeno", "porque_ref": "Ver mecanismo na conduta da lombociatalgia.", "linha": "Adjuvante sintomático"}], "referencias_gerais": [{"texto": "Portaria Conjunta SAES/SCTIE nº 33, de 19/01/2026: PCDT da Artrite Reumatoide (Ministério da Saúde). Localizada por busca; posologia completa NÃO lida. PENDENTE conferir em gov.br/saude.", "url": ""}, {"texto": "Fraenkel L et al. 2021 ACR Guideline. Arthritis Care Res. 2021;73(7):924-939. doi:10.1002/acr.24596. Referência localizada por busca; texto integral não lido.", "url": "https://doi.org/10.1002/acr.24596"}, {"texto": "Smolen JS et al. EULAR recommendations for the management of rheumatoid arthritis with synthetic and biological DMARDs: 2022 update. Ann Rheum Dis. 2023;82(1):3-18 (doi:10.1136/ard-2022-223356). Título, autores e escopo conferidos por busca; redação das recomendações não lida.", "url": ""}, {"texto": "SBR: Diretriz para tratamento medicamentoso da AR, Revista Brasileira de Reumatologia (2013). Localizada por busca; versão de 2024 NÃO encontrada.", "url": ""}], "hierarquia": ["1ª linha: metotrexato em monoterapia, em atividade moderada a alta (ACR 2021, recomendação forte).", "2ª linha: se não houver resposta, combinação com outro DMARD convencional ou biológico, conforme o PCDT vigente (Portaria 33/2026).", "3ª linha: outros biológicos ou inibidores de JAK, por especialista.", "Adjuvantes: ácido fólico com o metotrexato; glicocorticoide em ponte curta; AINE para sintoma.", "Hidroxicloroquina: primeira opção condicional em baixa atividade (ACR 2021)."]}, {"id": "sindrome-cauda-equina", "titulo": "Síndrome da cauda equina (urgência)", "caso": "Red flag da aula 8: retenção urinária, incontinência, anestesia em sela, déficit progressivo", "resumo": "Urgência neurocirúrgica. Não há medicamento que resolva a compressão. A conduta é imediata: RM de urgência e descompressão cirúrgica. O medicamento serve para dor e para as complicações.", "passos": [{"titulo": "1. Reconhecer", "texto": "Retenção ou incontinência urinária ou fecal, anestesia em sela, déficit motor bilateral ou progressivo, dor lombar com irradiação bilateral."}, {"titulo": "2. Encaminhar imediatamente", "texto": "Neurocirurgia de urgência. RM lombossacra de urgência. Não aguardar a evolução."}, {"titulo": "3. Medir o resíduo urinário", "texto": "Avaliar retenção com ultrassonografia de bexiga ou sondagem. Sondagem vesical de alívio, conforme o caso, pela equipe."}, {"titulo": "4. Analgesia", "texto": "Analgesia adequada à dor. Opioide pode ser necessário, em dose individualizada, sem deixar de tratar a causa."}, {"titulo": "5. Corticoide", "texto": "Uso de corticoide em alta dose é controverso e não substitui a descompressão. A decisão é da equipe, caso a caso."}], "medicacoes": [{"nome_comercial": "Morfina (ex.: morfina genérica)", "nome_generico": "Sulfato de morfina", "classe": "Analgésico opioide", "dose": "Individualizada: doses tituladas por via IV ou VO, conforme a resposta e a função renal", "posologia": "Conforme protocolo de analgesia do serviço, com reavaliação frequente.", "indicacao": "Dor intensa, quando a analgesia não-opioide não é suficiente, até a descompressão cirúrgica.", "porque": "Alívio da dor intensa, reduzindo o sofrimento até o tratamento da causa.", "mecanismo": ["Os receptores μ (mu) são proteínas na membrana de neurônios do cérebro, da medula e do intestino.", "Quando a morfina se liga ao receptor μ, a célula abre canais de potássio (o interior fica mais negativo, e a célula fica menos excitável) e fecha canais de cálcio.", "Sem cálcio suficiente, o neurônio não libera neurotransmissores de dor, como a substância P e o glutamato.", "Na medula, o sinal de dor é atenuado e não sobe ao cérebro com a mesma intensidade.", "Efeitos colaterais: o centro respiratório do tronco encefálico também é deprimido (risco de respirar menos), o intestino fica mais lento (constipação) e há náusea."], "efeitos_adversos": "Sedação, constipação, náusea, retenção urinária (agrava o quadro), depressão respiratória em dose excessiva.", "contraindicacoes": "Depressão respiratória grave, íleo paralítico, alergia. Cuidado com insuficiência renal e hepática.", "cuidados": "Monitorar sedação e frequência respiratória. Antídoto: naloxona.", "referencias": ["NICE NG59 (atualização 2020): opioides não recomendados para ciatalgia crônica; uso agudo sob supervisão. https://www.nice.org.uk/guidance/ng59", "Bula da morfina aprovada pela Anvisa (conferir versão atual)."], "termos": ["Receptor opioide μ: receptor que medeia analgesia e também depressão respiratória e constipação.", "Canal de potássio: canal que, ao abrir, deixa o potássio sair e torna a célula menos excitável.", "Canal de cálcio: canal que, ao abrir, deixa o cálcio entrar e dispara a liberação de neurotransmissores.", "Substância P: neurotransmissor da dor, liberado pelos neurônios aferentes."], "linha": "Adjuvante (dor intensa)"}, {"nome_comercial": "Paracetamol", "nome_generico": "Paracetamol", "classe": "Analgésico não opioide", "dose": "Ver conduta da lombociatalgia", "posologia": "Ver conduta da lombociatalgia", "indicacao": "Analgesia de base, em associação ao opioide se necessário.", "porque": "Reduzir a dose de opioide necessária.", "ref": "Paracetamol", "porque_ref": "Ver mecanismo na conduta da lombociatalgia.", "linha": "Adjuvante (analgesia)"}], "referencias_gerais": [{"texto": "NICE NG59 (2020): síndrome da cauda equina como urgência. Referência localizada por busca; texto integral não lido.", "url": "https://www.nice.org.uk/guidance/ng59"}, {"texto": "Diretriz AMB (2007): hérnia discal lombar, seção de urgência. Localizada por busca; PENDENTE conferir o trecho.", "url": ""}], "hierarquia": ["1ª linha: descompressão cirúrgica de urgência. Medicamento não resolve a compressão.", "Adjuvante: analgesia, com paracetamol como base e opioide titulado se necessário."]}, {"id": "fratura-exposta-trauma", "titulo": "Trauma grave com fratura exposta", "caso": "Red flag da aula 8: trauma grave, deformidade, crepitação, ferida próxima à fratura", "resumo": "Fratura exposta é urgência ortopédica e infecciosa. Antibiótico IV precoce, profilaxia do tétano, analgesia, lavagem e desbridamento cirúrgico. A classificação de Gustilo define o antibiótico.", "passos": [{"titulo": "1. Atendimento inicial (ATLS)", "texto": "Seguir a ordem: vias aéreas, respiração, circulação, déficit neurológico e exposição. Controlar sangramento com compressão e torniquete se necessário."}, {"titulo": "2. Avaliar o membro", "texto": "Pulsos distais, perfusão, sensibilidade e motricidade. Alteração neurovascular é urgência."}, {"titulo": "3. Antibiótico precoce", "texto": "Iniciar na primeira hora, antes do desbridamento. Cefazolina é o esquema usual. Em fraturas expostas de alta energia (Gustilo III), os esquemas variam: gentamicina somada à cefazolina, ou ceftriaxona com ou sem vancomicina, conforme o protocolo local."}, {"titulo": "4. Profilaxia do tétano", "texto": "Vacina antitetânica (dT) se o esquema estiver atrasado ou incompleto. Imunoglobulina antitetânica em ferida suja ou com esquema incompleto, conforme o protocolo."}, {"titulo": "5. Imobilização e imagem", "texto": "Imobilizar acima e abaixo da fratura. Radiografias em duas incidências. Não deixar exposição aberta sem cobertura estéril."}, {"titulo": "6. Cirurgia", "texto": "Lavagem abundante e desbridamento o quanto antes, com fixação. A cirurgia é a prioridade junto com o antibiótico."}, {"titulo": "7. Duração do antibiótico", "texto": "Fraturas tipo I e II: em geral até 24 horas após o fechamento ou a cobertura. Tipo III: duração maior, conforme o protocolo. As fontes variam; seguir o protocolo do serviço."}], "medicacoes": [{"nome_comercial": "Cefazolina (ex.: Kefazol)", "nome_generico": "Cefazolina sódica", "classe": "Cefalosporina de 1ª geração (β-lactâmico, bactericida)", "dose": "2 g IV (3 g se peso igual ou acima de 120 kg), por dose", "posologia": "IV a cada 8 horas. Nas fraturas tipo I e II, em geral 24 horas de uso, conforme protocolo.", "indicacao": "Profilaxia de infecção em fratura exposta tipos I e II. Cobre Staphylococcus aureus, que é o agente mais comum nessas fraturas.", "porque": "Evita osteomielite e infecção de ferida, que são complicações graves e de difícil tratamento.", "mecanismo": ["A cefazolina é uma cefalosporina de primeira geração com o mesmo mecanismo das demais: inativa as PBPs e impede a reticulação da parede.", "Ela tem bom efeito sobre Gram-positivos, sobretudo o Staphylococcus aureus, principal agente das fraturas expostas.", "Não atravessa bem a membrana dos Gram-negativos em quantidade suficiente para tratar fraturas de alta energia, por isso o esquema é ampliado nesses casos."], "efeitos_adversos": "Reações alérgicas, diarreia, flebite no local, leucopenia, Clostridioides difficile.", "contraindicacoes": "Alergia grave a β-lactâmicos (penicilinas e cefalosporinas), com cuidado em reações prévias. Usar clindamicina em alergia, conforme protocolo.", "cuidados": "Confirmar a história de alergia antes da primeira dose.", "referencias": ["Hauser CJ, Adams CA Jr, Eachempati SR. Surg Infect. 2006;7(4):379-405 (conferido por busca; texto original não acessado).", "Protocolos institucionais de fratura exposta (UAB, UT Houston e outros): cefazolina 2 g IV a cada 8 horas (3 g se 120 kg ou mais). Verificar o protocolo local."], "termos": ["Cefalosporina de 1ª geração: cefalosporina com maior ação sobre Gram-positivos.", "Staphylococcus aureus: bactéria Gram-positiva mais comum em infecções de ossos e articulações."], "linha": "1ª linha (Gustilo I e II)"}, {"nome_comercial": "Gentamicina (ex.: Garamicina)", "nome_generico": "Sulfato de gentamicina", "classe": "Aminoglicosídeo (bactericida, Gram-negativos)", "dose": "Conforme protocolo local, por dose ajustada ao peso e à função renal", "posologia": "IV, conforme protocolo, em geral em dose única diária, com monitorização de nível e função renal.", "indicacao": "Ampliação de cobertura para Gram-negativos em fratura exposta tipo III (alta energia, contaminação grave).", "porque": "Fraturas tipo III têm contaminação grave, com risco de Gram-negativos. A cefazolina sozinha não basta.", "mecanismo": ["A gentamicina entra na bactéria Gram-negativa pelas porinas e atravessa a membrana interna por transporte ativo, que depende do potencial elétrico da membrana.", "Dentro da bactéria, ela se liga à subunidade 30S do ribossomo, a máquina que lê o RNA mensageiro e monta proteínas.", "A ligação faz o ribossomo ler o código errado. Proteínas defeituosas são montadas.", "As proteínas defeituosas danificam a membrana e a bactéria morre (efeito bactericida).", "O efeito depende da concentração: quanto mais alta a concentração de pico, maior a morte bacteriana.", "Toxicidade: o fármaco se acumula no ouvido interno (células ciliadas) e no rim (túbulo proximal), o que causa perda auditiva e lesão renal."], "efeitos_adversos": "Nefrotoxicidade, ototoxicidade (vestibular e auditiva), bloqueio neuromuscular em dose alta.", "contraindicacoes": "Alergia a aminoglicosídeos, insuficiência renal grave, miastenia gravis. Cuidado em idosos e com outros nefrotóxicos.", "cuidados": "Monitorar função renal e nível sérico conforme protocolo. Limitar o uso ao necessário (aminoglicosídeo tem toxicidade cumulativa).", "referencias": ["Protocolos institucionais de fratura exposta (UT Houston; Harbor-UCLA). Conferir o protocolo local.", "Bula da gentamicina aprovada pela Anvisa (conferir versão atual)."], "termos": ["Ribossomo 30S: subunidade pequena do ribossomo bacteriano, alvo dos aminoglicosídeos.", "RNA mensageiro: molécula que leva o código do DNA até o ribossomo.", "Transporte ativo: movimento de uma substância contra o gradiente, com gasto de energia.", "Bactericida concentração-dependente: quanto maior a concentração de pico, mais bactérias morrem."], "linha": "2ª linha (Gustilo III)"}, {"nome_comercial": "Vacina dT e imunoglobulina antitetânica", "nome_generico": "Toxoide tetânico e difteria (dT); imunoglobulina humana antitetânica", "classe": "Vacina (imunização ativa) e imunoglobulina (imunização passiva)", "dose": "dT: 0,5 mL IM. Imunoglobulina antitetânica: dose conforme protocolo (em geral 250 UI IM).", "posologia": "Conforme o esquema vacinal do paciente e o tipo de ferida.", "indicacao": "Prevenção do tétano em ferida com risco.", "porque": "Ferida contaminada por solo e fraturas expostas são o cenário clássico do tétano.", "mecanismo": ["A dT induz produção de anticorpos contra a toxina tetânica, em semanas (imunização ativa).", "A imunoglobulina antitetânica já traz anticorpos prontos, que neutralizam a toxina que já circula (imunização passiva, ação imediata).", "A toxina tetânica bloqueia a liberação de glicina e GABA nos neurônios inibitórios, causando espasmo.", "Os anticorpos impedem que a toxina chegue ao sistema nervoso central."], "efeitos_adversos": "Dor e vermelhidão no local, febre leve. Imunoglobulina: reação local e, raramente, reação alérgica.", "contraindicacoes": "Reação anafilática prévia à vacina ou à imunoglobulina.", "cuidados": "Verificar o cartão vacinal. Em esquema incompleto, completar o esquema.", "referencias": ["Protocolos de profilaxia do tétano em ferimentos (verificar a versão atual do Ministério da Saúde e do serviço).", "Bula da vacina dT e da imunoglobulina aprovadas pela Anvisa (conferir versão atual)."], "linha": "Obrigatória (profilaxia)"}], "referencias_gerais": [{"texto": "Hauser CJ, Adams CA Jr, Eachempati SR. Surgical infection society guideline: prophylactic antibiotic use in open fractures. Surg Infect. 2006;7(4):379-405. Referência localizada por busca; texto integral não lido.", "url": ""}, {"texto": "Protocolos institucionais de fratura exposta (UAB, UT Houston, Vanderbilt, Harbor-UCLA): cefazolina 2 g IV a cada 8 h (3 g se 120 kg ou mais). Referência localizada por busca; texto integral não lido.", "url": ""}, {"texto": "Ministério da Saúde. Guia de Vigilância em Saúde (edições 2021 e 2024), tétano acidental. Notas técnicas estaduais (2025) divergem: IGHAT 250 UI IM como profilaxia em sítio separado da vacina, e SAT 5.000 UI quando a IGHAT não estiver disponível. PENDENTE conferir o texto oficial vigente.", "url": "https://www.gov.br/saude"}, {"texto": "ATLS, 10ª edição (American College of Surgeons, 2018): atendimento inicial ao trauma. Não conferido nesta busca. PENDENTE.", "url": ""}], "hierarquia": ["1ª linha antibiótica (Gustilo I e II): cefazolina IV a cada 8 horas (Hauser et al., 2006; protocolos institucionais).", "2ª linha antibiótica (Gustilo III): cefazolina somada à gentamicina, ou ceftriaxona com ou sem vancomicina, conforme o protocolo local.", "Obrigatório, independente da antibioticoterapia: profilaxia do tétano (dT e imunoglobulina antitetânica conforme o esquema).", "Adjuvante: analgesia com opioide titulado, se necessário."]}, {"id": "entorse-tornozelo", "titulo": "Entorse de tornozelo sem critério de radiografia (Ottawa negativo)", "caso": "Aula 8: trauma de tornozelo sem dor à palpação de maléolo ou de 5º metatarso, e com capacidade de dar 4 passos", "resumo": "Entorse leve a moderada. Proteger, gelo, elevação, analgesia e retorno precoce à atividade. Imobilização curta, se houver dor importante.", "passos": [{"titulo": "1. Confirmar Ottawa negativo", "texto": "Sem dor à palpação da borda posterior ou da ponta dos maléolos (6 cm distais), sem dor no mediopé com dor à palpação da base do 5º metatarso ou do navicular, e com capacidade de dar 4 passos. Se positivo em qualquer critério, radiografia."}, {"titulo": "2. Carga precoce e tratamento funcional", "texto": "O tratamento funcional (exercício e carga tolerada) é o método preferido. Imobilização só se dor ou edema importantes, por no máximo 10 dias, e depois iniciar o tratamento funcional. Órtese tipo bota tem os maiores efeitos entre os suportes funcionais."}, {"titulo": "3. Analgesia", "texto": "Paracetamol como base. AINE por curto período, se não houver contraindicação."}, {"titulo": "4. Gelo, compressão e elevação", "texto": "O protocolo RICE isolado não tem evidência de benefício para a entorse lateral aguda (Vuurberg et al., 2018). Pode ser usado como conforto, mas não como tratamento principal."}, {"titulo": "5. Reabilitação", "texto": "Amplitude de movimento, fortalecimento, treino de equilíbrio e propriocepção, e retorno gradual às atividades. Ultrassom e laser têm pouco ou nenhum benefício comprovado e não são recomendados."}, {"titulo": "6. Sinais de alarme e cirurgia", "texto": "Dor que piora, incapacidade de apoiar, deformidade ou dormência: reavaliar e considerar radiografia. Cirurgia é considerada em instabilidade persistente após tratamento funcional adequado."}], "medicacoes": [{"nome_comercial": "Ibuprofeno", "ref": "Ibuprofeno", "indicacao": "Analgesia e controle do edema nas primeiras 48 a 72 horas.", "porque": "Reduzir dor e edema no período agudo.", "linha": "Adjuvante (curto prazo)"}, {"nome_comercial": "Paracetamol", "ref": "Paracetamol", "indicacao": "Analgesia de base, sem efeito anti-inflamatório relevante.", "porque": "Dor sem risco gástrico do AINE.", "linha": "1ª linha analgésica"}], "referencias_gerais": [{"texto": "Stiell IG, Greenberg GH, McKnight RD, Nair RC, McDowell I, Worthington JR. A study to develop clinical decision rules for the use of radiography in acute ankle injuries. Ann Emerg Med. 1992;21(4):384-390. doi:10.1016/s0196-0644(05)82656-3. Referência localizada por busca; texto integral não lido.", "url": "https://doi.org/10.1016/s0196-0644(05)82656-3"}, {"texto": "Stiell IG, Greenberg GH, McKnight RD, et al. Decision rules for the use of radiography in acute ankle injuries: refinement and prospective validation. JAMA. 1993;269(9):1127-1132 (PMID 8433468). Referência localizada por busca; texto integral não lido. Derivação: Stiell IG et al. Ann Emerg Med. 1992;21(4):384-390.", "url": ""}, {"texto": "Vuurberg G, Hoorntje A, Wink LM, et al. Diagnosis, treatment and prevention of ankle sprains: update of an evidence-based clinical guideline. Br J Sports Med. 2018. Referência localizada por busca; texto integral não lido.", "url": ""}, {"texto": "Diretriz brasileira de entorse de tornozelo (SBOT ou SBMEE): NÃO localizada. PENDENTE conferir em sbot.org.br.", "url": ""}], "hierarquia": ["1ª linha: tratamento funcional com exercício e carga tolerada (Vuurberg et al., BJSM 2018).", "1ª linha analgésica: paracetamol.", "Adjuvante: AINE por curto período."]}]};
